        public List<VehiclePurchaseOrHireDetails> ReadAllVehicleDetails(SqlDataReader aoSqlDataReader)
        {
            List<VehiclePurchaseOrHireDetails> lstVehiclePurchaseOrHireDetails = new List<VehiclePurchaseOrHireDetails>();
            if (aoSqlDataReader != null)
            {
