        /// <summary>
        /// This method is used to get all vehicles associated with Stops & shifts.
        /// </summary>
        /// <param name="aiUserId"></param>
        /// <returns></returns>
        public List<VehicleDetails> GetVehicles(int aiRouteId, int aiStopId, int aiShiftId)
        {
            List<VehicleDetails> lstVehicleDetail = new List<VehicleDetails>();
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", this.miSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYearId", this.miAcademicYearId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("RouteId", aiRouteId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("StopId", aiStopId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("ShiftId", aiShiftId, SqlDbType.Int);
                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("Transport.usp_GetVehicles"))
                {
                    while (oSqlDataReader.Read())
                    {
                        VehicleDetails oVehicleDetails = new VehicleDetails
                        {
                            VehicleId = oSqlDataReader["VehicleId"].ToInt(),
                            VehicleNumber = oSqlDataReader["VehicleNumber"].ToString()
                        };

                        lstVehicleDetail.Add(oVehicleDetails);
                    }
                }
            }

            return lstVehicleDetail;
        }

