                {
                    while (oSqlDataReader.Read())
                    {   
                        VehicleOptionDate oVehicleOptionDate = new VehicleOptionDate();
                        oVehicleOptionDate.VehicleId = oSqlDataReader["VehicleId"].ToInt();
                        oVehicleOptionDate.ExpiryDate = oSqlDataReader["ExpiryDate"].ToDateTime().ToString(Constants.S_DATE_FORMAT);
                        oVehicleOptionDate.PassingDate = oSqlDataReader["PassingDate"].ToDateTime().ToString(Constants.S_DATE_FORMAT);

                        lstVehicleOptionDate.Add(oVehicleOptionDate);
                    }

                }

                return lstVehicleOptionDate;
            }
        }

        /// <summary>
        /// This method is used to Get user transport history details to fill listview.
        /// </summary>
        /// <param name="aiUserId"></param>
        /// <returns></returns>
        public List<TransportHistoryDetails> GetUserTransportHistory(int aiUserId)
        {
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                List<TransportHistoryDetails> lstTransportHistoryDetails = new List<TransportHistoryDetails>();
                oSQLServerDbUtility.AddParameter("SchoolId", this.miSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYearId", this.miAcademicYearId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("UserId", aiUserId, SqlDbType.Int);

                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("[Transport].[usp_GetUserTransportHistory]"))
                {
                    while (oSqlDataReader.Read())
                    {
                        TransportHistoryDetails oTransportHistoryDetails = new TransportHistoryDetails();
                        oTransportHistoryDetails.SrNo = oSqlDataReader["SrNo"].ToInt();
                        oTransportHistoryDetails.UserId = oSqlDataReader["UserId"].ToInt();
                        oTransportHistoryDetails.UserName = oSqlDataReader["UserName"].ToString();         
                        oTransportHistoryDetails.Route = oSqlDataReader["Route"].ToString();
                        oTransportHistoryDetails.Stop = oSqlDataReader["Stop"].ToString();
                        oTransportHistoryDetails.Shift = oSqlDataReader["Shift"].ToString();
                        oTransportHistoryDetails.VehicleNumber = oSqlDataReader["VehicleNo"].ToString();
                        
                        if (oSqlDataReader["TransportLeftDate"] != DBNull.Value)
                            oTransportHistoryDetails.LeftDate = oSqlDataReader["TransportLeftDate"].ToDateTime();
                        if (oSqlDataReader["EffectiveFromDate"] != DBNull.Value)
                            oTransportHistoryDetails.EffectiveFromDate = oSqlDataReader["EffectiveFromDate"].ToDateTime();
                        if (oSqlDataReader["EffectiveToDate"] != DBNull.Value)
                            oTransportHistoryDetails.EffectiveToDate = oSqlDataReader["EffectiveToDate"].ToDateTime();

                        lstTransportHistoryDetails.Add(oTransportHistoryDetails);
                    }
                }
                return lstTransportHistoryDetails;
            }
        }

        public VehicleMasterToSync GetVehicleDetails(int aiSchoolId, string asVehicleNumber)
        {
            VehicleMasterToSync oVehicleMaster = new VehicleMasterToSync();
            oVehicleMaster.journeys = new List<ShiftMasterToSync>();

            List<StopMasterToSync> lstStops = new List<StopMasterToSync>();
            List<ShiftMasterToSync> lstJourneys = new List<ShiftMasterToSync>();

            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId",aiSchoolId,SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("VehicleNo", asVehicleNumber, SqlDbType.NVarChar);

                using (SqlDataReader oIDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("[Transport].[usp_GetVehicleDetails]"))
                {
                    while (oIDataReader.Read())
                    {
                        StopMasterToSync oStopMaster = new StopMasterToSync();
                        oStopMaster.stopId = oIDataReader["StopId"].ToInt();
                        oStopMaster.stopName = oIDataReader["StopName"].ToString();
                        oStopMaster.stopTime = oIDataReader["stopTime"].ToString();
                        oStopMaster.JourneyId = oIDataReader["TransportShiftId"].ToInt();
                        oStopMaster.latitude = oIDataReader["Latitude"].ToString();
                        oStopMaster.longitude = oIDataReader["Longitude"].ToString();
                        oStopMaster.landmark = oIDataReader["Landmark"].ToString();

                        lstStops.Add(oStopMaster);
                    }

                    oIDataReader.NextResult();
                    while (oIDataReader.Read())
                    {
                        string[] workingDays = { "MONDAY", "TUESDAY", "WEDNESDAY", "THURSDAY", "FRIDAY", "SATURDAY" };
                        ShiftMasterToSync oShiftMaster = new ShiftMasterToSync();
                        oShiftMaster.journeyId = oIDataReader["TransportShiftId"].ToInt();
                        oShiftMaster.journeyName = oIDataReader["TransportShiftName"].ToString();
                        oShiftMaster.journeyType = oIDataReader["journeyType"].ToString();
                        oShiftMaster.startTime = oIDataReader["startTime"].ToString();
                        oShiftMaster.endTime = oIDataReader["endTime"].ToString();
                        oShiftMaster.workingDays = workingDays;

                        oShiftMaster.stops = lstStops.Where(st => st.JourneyId == oShiftMaster.journeyId).ToList();

                        lstJourneys.Add(oShiftMaster);
                    }

                    oIDataReader.NextResult();
                    if (oIDataReader.Read())
                    {
                        oVehicleMaster.thingId = oIDataReader["VehicleNumber"].ToString();
                        oVehicleMaster.thingName = oIDataReader["VehicleName"].ToString();
                        oVehicleMaster.journeys = lstJourneys;
                    }
                }
            }

            return oVehicleMaster;
        }

        public void UpdateTrackingURL(int aiSchoolId, int aiAcademicYearId, int aiUpdatedById, int aiVehicleId, string asTrackingURL)
        {
            string sUpdateStatement = "UPDATE [TRANSPORT].[VehicleMaster] " +
                    "SET TrackingURL='" + asTrackingURL + "'," +
                    "UpdateDate = DBO.GetLocalDate(default)," +
                    "UpdatedById=" + aiUpdatedById +
                    " WHERE SchoolId=" + aiSchoolId +
                    " AND Academic_Year_Id=" + aiAcademicYearId +
                    " AND VehicleId=" + aiVehicleId;
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.ExecuteTransaction(sUpdateStatement);
            }
        }

        public List<VehicleDetails> GetVehicles(int aiRouteId)
        {
            List<VehicleDetails> lstVehicleDetail = new List<VehicleDetails>();
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", this.miSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("AcademicYearId", this.miAcademicYearId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("RouteId", aiRouteId, SqlDbType.Int);
                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("[Transport].[usp_GetVehiclesOfRoute]"))
                {
                    while (oSqlDataReader.Read())
                    {
                        VehicleDetails oVehicleDetails = new VehicleDetails
                        {
                            VehicleId = oSqlDataReader["VehicleId"].ToInt(),
                            VehicleNumber = oSqlDataReader["VehicleNumber"].ToString()
                        };

                        lstVehicleDetail.Add(oVehicleDetails);
                    }
                }
            }

            return lstVehicleDetail;
        }
    }
